<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {api} from '../api';import type {WorkTab} from '../stores';import Modal from '../components/Modal.vue';import TransferCreate from '../components/TransferCreate.vue';import TransferConfirm from '../components/TransferConfirm.vue';import TransferCorrect from '../components/TransferCorrect.vue';import TransferHistory from '../components/TransferHistory.vue';
const props=defineProps<{tab:WorkTab;embedded?:boolean}>(),data=ref<any>(null),status=ref('pending'),search=ref(''),page=ref(1),loading=ref(false),error=ref(''),message=ref(''),reject=ref<any>(null),creating=ref(false),confirming=ref<any>(null),correcting=ref<any>(null),history=ref<any>(null),canCreate=ref(false);
const labels:Record<string,string>={pending:'待確認',confirmed:'已確認',rejected:'已拒絕'};
const rows=computed(()=>(data.value?.rows||[]).filter((r:any)=>[r.employee_code,r.employee_name,r.from_store?.store_name,r.to_store?.store_name].join(' ').toLowerCase().includes(search.value.trim().toLowerCase()))),pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/100))),visible=computed(()=>rows.value.slice((page.value-1)*100,page.value*100));
watch(search,()=>page.value=1);
function time(value:string){return value?new Date(value).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false}):'—';}
async function load(){loading.value=true;error.value='';data.value=null;try{data.value=await api('transfers?status='+status.value);canCreate.value=data.value.canCreate;page.value=1;}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function refuse(){if(!reject.value||props.tab.busy)return;const record=reject.value;reject.value=null;props.tab.busy=true;error.value='';message.value='';try{await api('transfers',{method:'POST',body:JSON.stringify({operation:'reject',id:record.id})});message.value=`已拒絕 ${record.employee_code} ${record.employee_name} 的調店申請。`;await load();}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
async function created(code:string){creating.value=false;message.value=`已送出 ${code} 的調店申請，等待督導確認。`;status.value='pending';search.value=code;await load();}
async function confirmed(result:any){const record=confirming.value;confirming.value=null;message.value=`已確認 ${record.employee_code} 的調店（${result?.side==='admin'?sideText.admin:(sideText[result?.side]||'督導')+'確認'}），主檔與月資料已同步。`+(result?.actingContinued?'已在新店自動登記代理店長異動。':result?.actingEnded?'代理註記已隨調店結束。':'');await load();}
const sideText:Record<string,string>={from:'原店督導',to:'新店督導',both:'原店與新店督導',admin:'系統管理員代確認'};
async function corrected(){correcting.value=null;message.value='調店日期已更正，異動、主檔與當月天數已同步。';await load();}
onMounted(load);
</script>
<template><header class="page-heading"><div><p v-if="!embedded" class="eyebrow">組織與門市 / 人員異動管理</p><h1 v-if="!embedded">調店登記確認</h1><p>調店由原店或新店任一位督導確認即生效（系統管理員可代確認並留下紀錄）；批次輸入的調店也會在這裡等待確認。</p></div><button :disabled="loading||tab.busy" @click="load">重新整理</button></header><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><p v-if="loading" role="status">正在載入申請…</p>
<button v-if="canCreate&&!creating" class="primary" :disabled="loading||tab.busy" @click="creating=true">新增調店申請</button><TransferCreate v-if="creating" :tab="tab" @cancel="creating=false" @saved="created"/>
<div class="filters"><label>申請狀態<select v-model="status" aria-label="申請狀態" :disabled="loading||tab.busy" @change="load"><option value="all">全部狀態</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><label>搜尋申請<input v-model="search" placeholder="員編、姓名、原門市或新門市"></label></div>
<template v-if="data"><p>符合 {{rows.length}} / {{data.rows.length}} 筆申請</p><div class="module-table"><table><thead><tr><th>員編／姓名</th><th>原任職門市 → 新任職門市</th><th>狀態／生效日</th><th>申請／處理</th><th>備註與更正</th><th>操作</th></tr></thead><tbody><tr v-for="r in visible" :key="r.id"><td>{{r.employee_code}}<br>{{r.employee_name}}</td><td>{{r.from_store?.store_code}} {{r.from_store?.store_name||'未提供'}}<br>→ {{r.to_store?.store_code}} {{r.to_store?.store_name||'未提供'}}</td><td>{{labels[r.status]||r.status}}<br>{{r.effective_date||(r.requested_date?'預定 '+r.requested_date:'未指定生效日')}}<div v-if="r.status!=='rejected'" class="sides" data-testid="transfer-confirmation"><template v-if="r.status==='confirmed'&&r.confirmation"><strong>確認：</strong>{{r.confirmation.proxy?'系統管理員代確認':sideText[r.confirmation.side]}}（{{r.confirmation.by_name}}）</template><template v-else-if="r.status==='pending'"><strong>待確認</strong>：原店或新店任一位督導確認即可<br><small>原店督導：{{r.supervisors?.from?.length?r.supervisors.from.join('、'):'無督導'}}／新店督導：{{r.supervisors?.to?.length?r.supervisors.to.join('、'):'無督導'}}</small><small v-if="!r.supervisors?.from?.length&&!r.supervisors?.to?.length">（兩店都沒有督導，需系統管理員代確認）</small></template><template v-else>—</template></div></td><td>{{r.creator_name||'未提供申請人'}}<br>{{time(r.created_at)}}<template v-if="r.confirmed_at"><br>{{r.confirmer_name||'未提供處理人'}}<br>{{time(r.confirmed_at)}}</template></td><td class="notes">{{r.notes||'—'}}<template v-if="r.status==='pending'&&r.continue_acting"><hr><span data-testid="acting-continue-tag">申請上已選：新店續任代理店長（確認生效時自動在新店登記）。</span></template><template v-else-if="r.acting_movement_id"><hr><span data-testid="acting-continue-tag">新店續任代理店長：已自動登記代理異動（生效日同調店日）。</span></template><template v-else-if="r.acting_ended"><hr><span data-testid="acting-ended-tag">原為代理店長，代理註記已隨調店結束。</span></template><template v-if="r.corrected_at"><hr>{{r.correction_reason}}<br>{{r.corrector_name||'未提供更正人'}} · {{time(r.corrected_at)}}</template></td><td><button v-if="r.canConfirm" :disabled="tab.busy||loading||creating" @click="confirming=r">確認調店</button><button v-if="r.canReject" class="danger" :disabled="tab.busy||loading" @click="reject=r">拒絕申請</button><button v-if="r.canCorrect" :disabled="tab.busy||loading||creating" @click="correcting=r">更正日期</button><button v-if="r.corrected_at" :disabled="tab.busy" @click="history=r">更正紀錄</button><span v-if="!r.canConfirm&&!r.canReject&&!r.canCorrect&&!r.corrected_at">—</span></td></tr><tr v-if="!rows.length"><td colspan="6">沒有符合條件的調店申請。</td></tr></tbody></table></div><div class="pagination"><span>第 {{page}} / {{pages}} 頁</span><button :disabled="page===1" @click="page--">上一頁</button><button :disabled="page===pages" @click="page++">下一頁</button></div></template>
<TransferHistory v-if="history" :record="history" @close="history=null"/><TransferCorrect v-if="correcting" :record="correcting" :tab="tab" @cancel="correcting=null" @saved="corrected"/><TransferConfirm v-if="confirming" :record="confirming" :tab="tab" @cancel="confirming=null" @saved="confirmed"/><Modal v-if="reject" title="確認拒絕調店申請" @cancel="reject=null"><p>{{reject.employee_code}} {{reject.employee_name}}</p><p>{{reject.from_store?.store_name}} → {{reject.to_store?.store_name}}</p><p>拒絕後此申請不會進行調店。</p><div class="dialog-actions"><button @click="reject=null">返回</button><button class="danger" @click="refuse">確認拒絕</button></div></Modal></template>
<style scoped>.filters{display:flex;gap:16px;flex-wrap:wrap;margin:24px 0}label{display:grid;gap:8px}.filters input{width:300px;max-width:100%}.module-table table{min-width:1100px}.module-table td{white-space:normal;overflow-wrap:anywhere}.sides{margin-top:8px;font-size:13px;line-height:1.6}.sides small{color:var(--muted)}.notes{white-space:pre-wrap!important;min-width:200px;max-width:350px}.pagination{display:flex;gap:12px;align-items:center;margin-top:20px}.pagination span{margin-right:auto}@media(max-width:600px){.filters{display:grid}.filters input,.filters select{width:100%}}</style>
